import{VoxelPart}from'./voxels.js?v=balance-8';
const B=globalThis.BABYLON,V=B.Vector3;
// Each fragment contains the original solid voxels; rebuilding exposes closed fracture faces.
export function fractureVoxels(mesh,scene){const source=mesh.sourceMesh||mesh,meta=source.metadata;if(!meta?.voxelCells?.length)return[];return fractureCells(meta.voxelCells,meta.voxelSize,mesh.computeWorldMatrix(true).clone(),mesh.name,scene);}
export function fractureCells(cells,size,matrix,name,scene){const scale=V.One(),rotation=B.Quaternion.Identity(),position=V.Zero();matrix.decompose(scale,rotation,position);
 let min=V.One().scale(Infinity),max=V.One().scale(-Infinity);for(const c of cells){min=V.Minimize(min,new V(c.x,c.y,c.z));max=V.Maximize(max,new V(c.x,c.y,c.z));}const span=max.subtract(min),step=Math.max(2,Math.ceil(span.length()/7)),groups=new Map();for(const c of cells){const key=[Math.floor((c.x-min.x)/step),Math.floor((c.y-min.y)/step),Math.floor((c.z-min.z)/step)].join('/');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(c);}
 const fragments=[];for(const group of groups.values()){const center=new V();for(const c of group)center.addInPlace(new V(c.x,c.y,c.z));center.scaleInPlace(1/group.length);center.set(Math.round(center.x),Math.round(center.y),Math.round(center.z));const part=new VoxelPart('impact fragment · '+name,scene,null,size);for(const c of group)part.set(c.x-center.x,c.y-center.y,c.z-center.z,c.color);part.build();const fragment=part.mesh;fragment.parent=null;fragment.position.copyFrom(V.TransformCoordinates(center.scale(size),matrix));fragment.scaling.copyFrom(scale);fragment.rotationQuaternion=rotation.clone();part.node.dispose(false,false);fragment.computeWorldMatrix(true);fragments.push({mesh:fragment,count:group.length});}return fragments;
}
